-- Pomir Wings -- demo airline database (fictional data, generated for BI dashboard demos)
-- Generated automatically, safe to import into an empty MySQL schema.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `baggage`;
DROP TABLE IF EXISTS `payments`;
DROP TABLE IF EXISTS `bookings`;
DROP TABLE IF EXISTS `passengers`;
DROP TABLE IF EXISTS `flight_crew`;
DROP TABLE IF EXISTS `maintenance_records`;
DROP TABLE IF EXISTS `flights`;
DROP TABLE IF EXISTS `routes`;
DROP TABLE IF EXISTS `employees`;
DROP TABLE IF EXISTS `aircraft`;
DROP TABLE IF EXISTS `aircraft_models`;
DROP TABLE IF EXISTS `airports`;

CREATE TABLE `airports` (
    `airport_id` INT PRIMARY KEY,
    `iata_code` CHAR(3) NOT NULL UNIQUE,
    `name` VARCHAR(150) NOT NULL,
    `city` VARCHAR(100) NOT NULL,
    `country` VARCHAR(100) NOT NULL,
    `latitude` DECIMAL(9,6) NOT NULL,
    `longitude` DECIMAL(9,6) NOT NULL,
    `timezone` VARCHAR(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `aircraft_models` (
    `model_id` INT PRIMARY KEY,
    `manufacturer` VARCHAR(50) NOT NULL,
    `model_name` VARCHAR(50) NOT NULL,
    `seats_economy` INT NOT NULL,
    `seats_business` INT NOT NULL,
    `range_km` INT NOT NULL,
    `cruise_speed_kmh` INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `aircraft` (
    `aircraft_id` INT PRIMARY KEY,
    `tail_number` VARCHAR(10) NOT NULL UNIQUE,
    `model_id` INT NOT NULL,
    `year_built` YEAR NOT NULL,
    `status` ENUM('active','maintenance','retired') NOT NULL,
    `base_airport_id` INT NOT NULL,
    FOREIGN KEY (`model_id`) REFERENCES `aircraft_models`(`model_id`),
    FOREIGN KEY (`base_airport_id`) REFERENCES `airports`(`airport_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employees` (
    `employee_id` INT PRIMARY KEY,
    `first_name` VARCHAR(50) NOT NULL,
    `last_name` VARCHAR(50) NOT NULL,
    `position` ENUM('pilot','co-pilot','flight_attendant','ground_staff','manager','mechanic','dispatcher') NOT NULL,
    `hire_date` DATE NOT NULL,
    `salary` DECIMAL(10,2) NOT NULL,
    `base_airport_id` INT NOT NULL,
    `email` VARCHAR(150) NOT NULL,
    FOREIGN KEY (`base_airport_id`) REFERENCES `airports`(`airport_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `routes` (
    `route_id` INT PRIMARY KEY,
    `origin_airport_id` INT NOT NULL,
    `destination_airport_id` INT NOT NULL,
    `distance_km` INT NOT NULL,
    `base_price` DECIMAL(10,2) NOT NULL,
    FOREIGN KEY (`origin_airport_id`) REFERENCES `airports`(`airport_id`),
    FOREIGN KEY (`destination_airport_id`) REFERENCES `airports`(`airport_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `flights` (
    `flight_id` INT PRIMARY KEY,
    `flight_number` VARCHAR(6) NOT NULL,
    `route_id` INT NOT NULL,
    `aircraft_id` INT NOT NULL,
    `scheduled_departure` DATETIME NOT NULL,
    `scheduled_arrival` DATETIME NOT NULL,
    `actual_departure` DATETIME NULL,
    `actual_arrival` DATETIME NULL,
    `status` ENUM('scheduled','departed','arrived','delayed','cancelled') NOT NULL,
    `delay_minutes` INT NOT NULL DEFAULT 0,
    FOREIGN KEY (`route_id`) REFERENCES `routes`(`route_id`),
    FOREIGN KEY (`aircraft_id`) REFERENCES `aircraft`(`aircraft_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `flight_crew` (
    `id` INT PRIMARY KEY,
    `flight_id` INT NOT NULL,
    `employee_id` INT NOT NULL,
    `role_on_flight` VARCHAR(30) NOT NULL,
    FOREIGN KEY (`flight_id`) REFERENCES `flights`(`flight_id`),
    FOREIGN KEY (`employee_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `passengers` (
    `passenger_id` INT PRIMARY KEY,
    `first_name` VARCHAR(50) NOT NULL,
    `last_name` VARCHAR(50) NOT NULL,
    `birth_date` DATE NOT NULL,
    `nationality` VARCHAR(50) NOT NULL,
    `loyalty_tier` ENUM('none','silver','gold','platinum') NOT NULL,
    `email` VARCHAR(150) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bookings` (
    `booking_id` INT PRIMARY KEY,
    `flight_id` INT NOT NULL,
    `passenger_id` INT NOT NULL,
    `booking_date` DATETIME NOT NULL,
    `travel_class` ENUM('economy','business') NOT NULL,
    `seat_number` VARCHAR(4) NOT NULL,
    `price` DECIMAL(10,2) NOT NULL,
    `status` ENUM('confirmed','checked_in','cancelled','no_show') NOT NULL,
    FOREIGN KEY (`flight_id`) REFERENCES `flights`(`flight_id`),
    FOREIGN KEY (`passenger_id`) REFERENCES `passengers`(`passenger_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payments` (
    `payment_id` INT PRIMARY KEY,
    `booking_id` INT NOT NULL,
    `amount` DECIMAL(10,2) NOT NULL,
    `payment_method` ENUM('card','cash','bank_transfer','online_wallet') NOT NULL,
    `payment_date` DATETIME NOT NULL,
    `status` ENUM('paid','refunded','pending') NOT NULL,
    FOREIGN KEY (`booking_id`) REFERENCES `bookings`(`booking_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `baggage` (
    `baggage_id` INT PRIMARY KEY,
    `booking_id` INT NOT NULL,
    `weight_kg` DECIMAL(5,2) NOT NULL,
    `fee` DECIMAL(8,2) NOT NULL,
    FOREIGN KEY (`booking_id`) REFERENCES `bookings`(`booking_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `maintenance_records` (
    `record_id` INT PRIMARY KEY,
    `aircraft_id` INT NOT NULL,
    `maintenance_date` DATE NOT NULL,
    `type` ENUM('routine','repair','inspection') NOT NULL,
    `cost` DECIMAL(10,2) NOT NULL,
    `duration_hours` INT NOT NULL,
    `notes` VARCHAR(255) NOT NULL,
    FOREIGN KEY (`aircraft_id`) REFERENCES `aircraft`(`aircraft_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


